const failing = (stdout) => new Set([...stdout.matchAll(/^\s*✖ (.+?) \(\d+(?:\.\d+)?ms\)$/gm)].map((m) => m[1]));
// The process deadline bounds a hung suite; a process timeout is inconclusive.
// MUTATION_SUITE="worker/test/subtitles.test.js" runs only those test files per mutation (a kill there is a kill; a survivor should then be run against the whole suite),
// MUTATION_TIMEOUT_MS sets the time one run is given (12/10/2026: on a machine with a load average above 20 the whole root suite no longer finishes in 3 minutes, and then every
// mutation used to count a hang as killed: this version refuses that receipt).
const suiteArgs = (process.env.MUTATION_SUITE || "").split(/\s+/).filter(Boolean);
const suiteTimeoutMs = Number(process.env.MUTATION_TIMEOUT_MS) || 180000;
const suite = () => spawnSync(process.execPath, ["--test", "--test-reporter=spec", "--test-concurrency=1", ...suiteArgs], { cwd: root, encoding: "utf8", timeout: suiteTimeoutMs, killSignal: "SIGKILL", env: { ...process.env, SKIP_RSS: "1" } });
const base = suite();
const total = Number((base.stdout.match(/^ℹ tests (\d+)/m) || [])[1]);
if (base.status !== 0 || !total || !/^ℹ pass \d+/m.test(base.stdout)) { console.error("INCONCLUSIVE: baseline must run recognized nonzero tests with no failures", base.stderr, base.stdout); process.exit(2); }
const BASELINE = failing(base.stdout);
console.log(`baseline: ${(base.stdout.match(/^ℹ pass (\d+)/m) || [])[1]} green, ${BASELINE.size} red already${BASELINE.size ? ":" : ""}`);
for (const name of BASELINE) console.log(`   (red before any mutation, ignored) ${name.slice(0, 110)}`);

const only = process.argv[2];
const todo = M.filter(([, name]) => !only || name.includes(only));
const originals = new Map();
const restore = () => { for (const [file, text] of originals) fs.writeFileSync(path.join(root, file), text); };
process.on("SIGINT", () => { restore(); process.exit(130); });
process.on("exit", restore);

const rows = [];
for (const [file, name, find, replace] of todo) {
  if (!originals.has(file)) originals.set(file, fs.readFileSync(path.join(root, file), "utf8"));
  const text = originals.get(file);
  const n = text.split(find).length - 1;
  if (n !== 1) { rows.push({ name, file, verdict: `STALE (text found ${n} times)` }); continue; }
  fs.writeFileSync(path.join(root, file), text.replace(find, () => replace));
  const r = suite();
  fs.writeFileSync(path.join(root, file), text);
  const newlyRed = [...failing(r.stdout)].filter((n) => !BASELINE.has(n));
  const hung = r.error && r.error.code === "ETIMEDOUT";
  const crashed = !hung && r.status !== 0 && !failing(r.stdout).size; // the suite did not run: an inconclusive result
  const inconclusive = hung || crashed || (r.status !== 0 && (!newlyRed.length || !/ERR_ASSERTION|AssertionError/.test(r.stdout + r.stderr)));
  const killed = !inconclusive && newlyRed.length > 0;
  const first = newlyRed[0] ? newlyRed[0].slice(0, 100) : hung ? "the suite hung (no end in 3 minutes)" : crashed ? "the suite did not run" : "";
  rows.push({ name, file, verdict: inconclusive ? "INCONCLUSIVE" : killed ? "KILLED" : "SURVIVED", fails: newlyRed.length, first });
  console.log(`${(inconclusive ? "INCONCLUSIVE" : killed ? "KILLED  " : "SURVIVED").padEnd(9)} ${String(newlyRed.length).padStart(3)} red  ${name}${killed ? `   ← ${first}` : ""}`);
}
const killed = rows.filter((r) => r.verdict === "KILLED").length, survived = rows.filter((r) => r.verdict === "SURVIVED"), stale = rows.filter((r) => r.verdict.startsWith("STALE"));
console.log(`\n${killed} of ${rows.length} mutations make the suite red${survived.length ? `; SURVIVED: ${survived.map((r) => r.name).join("; ")}` : ""}${stale.length ? `; STALE: ${stale.map((r) => r.name).join("; ")}` : ""}`);
const inconclusive = rows.filter(r => r.verdict === "INCONCLUSIVE");
if (inconclusive.length) console.log("INCONCLUSIVE: " + inconclusive.map(r => r.name).join("; "));
process.exit(survived.length || stale.length || inconclusive.length ? 1 : 0);
